//! The Fadal library (data/machines/fadal.toml, generated by tools/machines/fadal.py from
//! fadal.com's spec tables): real and cited, the published numbers in place.
use forge_machine::def::{CiteStatus, MachineDef};
use forge_machine::library::{builtin_files, builtin_named};

#[test]
fn fadal_records_are_real_and_cited() {
    let ms: Vec<MachineDef> = builtin_files()
        .into_iter()
        .filter(|(_, f)| f == "builtin/fadal.toml")
        .map(|(m, _)| m)
        .collect();
    assert_eq!(ms.len(), 8);
    for m in &ms {
        assert!(m.real, "{}", m.name);
        for p in m.cite_paths() {
            assert!(m.cites.iter().any(|c| c.path == p), "{}: {p}", m.name);
        }
    }
    let m = builtin_named("fadal-vmc-4020b-ii").unwrap();
    assert_eq!(m.joint("X").unwrap().range, Some([-1016.0, 0.0])); // 40 in
    assert_eq!(m.joint("X").unwrap().rapid, Some(25400.0)); // 1,000 IPM
    assert_eq!(m.spindles[0].nose[2], 635.0); // 5-25 in: 25 in at the top
    assert_eq!(m.spindles[0].rpm.unwrap()[1], 10000.0);
    // the page's text says 900 IPM, its table 1,000: recorded
    assert!(
        m.cites
            .iter()
            .any(|c| c.path == "joint.X.rapid" && c.status == CiteStatus::Conflict)
    );
    let b = builtin_named("fadal-vmc-8032-50t").unwrap();
    assert_eq!(b.spindles[0].interface, "CAT50");
    assert_eq!(b.joint("Z").unwrap().rapid, Some(590.0 * 25.4));
}
